from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='En el siglo XVII la Monarquía Hispánica siguió siendo una gran potencia, pero con crecientes dificultades internas y externas. Este capítulo estudia cuatro episodios: la expulsión de los moriscos bajo Felipe III, el programa de Olivares bajo Felipe IV, la paz con Francia en 1659 y el reinado de Carlos II, que terminó sin heredero. Como en capítulos anteriores, se señalan las cifras que las fuentes no consiguen conciliar.',
        quotes=[Q('es_moriscos','La expulsión de los moriscos de España fue ordenada por el rey Felipe III y llevada a cabo de forma escalonada entre 1609 y 1613.'), Q('en_olivares','During his rule, he over-exerted Spain in foreign affairs and unsuccessfully attempted domestic reform.')]))
    P.append(dict(text='La expulsión de los moriscos, descendientes de la población musulmana que había sido obligada a convertirse, fue ordenada por Felipe III. Una fuente da como fecha del decreto el 9 de abril de 1609 y habla de decretos hasta 1614; la otra la sitúa entre 1609 y 1613 y detalla el calendario por territorios: Valencia (22 de septiembre de 1609), Andalucía (10 de enero de 1610), Corona de Aragón (29 de mayo de 1610), Extremadura y las dos Castillas (10 de julio de 1610) y Murcia (de octubre de 1610 a octubre de 1613).',
        quotes=[Q('en_moriscos','was decreed by King Philip III of Spain on April 9, 1609'), Q('en_moriscos','Between 1609 and 1614, the Crown systematically expelled Moriscos'), Q('es_moriscos','Los primeros moriscos expulsados fueron los del Reino de Valencia (el decreto se hizo público el 22 de septiembre de 1609)','(octubre de 1613)')]))
    P.append(dict(text='Las cifras de la expulsión no concuerdan. Una fuente dice que fueron expulsadas unas 350 000 personas, pero también que la población morisca era de unas 325 000, de modo que la cifra de expulsados supera la de moriscos que existían, una incoherencia que se calcula en el problema resuelto de este capítulo. La otra fuente recoge estimaciones de entre 275 000 y 300 000 expulsados, un 4 % de la población española, y señala que historiadores recientes, como Trevor Dadson, calculan una población morisca de 500 000, de la que cerca del 40 % evitó la expulsión.',
        quotes=[Q('es_moriscos','En total fueron expulsadas unas 350 000 personas'), Q('es_moriscos','La población morisca consistía en unas 325 000 personas en un país de unos 8,5 millones de habitantes.'), Q('en_moriscos','range between 275,000 and 300,000 Moriscos (or 4% of the total Spanish population)'), Q('en_moriscos','Dadson estimates that, out of a Morisco population of 500,000, a figure accepted by many, around 40% avoided expulsion altogether')]))
    P.append(dict(text='El impacto fue desigual. Según una fuente, los más afectados fueron Valencia y Aragón, que perdieron un tercio y un sexto de su población, respectivamente. La otra fuente añade que en Valencia, donde los musulmanes eran la mayor parte del campesinado, la expulsión fue más severa y provocó el hundimiento económico y la despoblación de gran parte del territorio, agravados por la peste que llegó pocos años después. Entre 30 000 y 75 000 de los expulsados habrían regresado.',
        quotes=[Q('es_moriscos','la mayoría de ellas de los reinos de Valencia y de Aragón que fueron los más afectados, ya que perdieron un tercio y un sexto de su población, respectivamente'), Q('en_moriscos','leading to the economic collapse and depopulation of much of its territory'), Q('en_moriscos','with around 30,000 to 75,000 people ultimately returning to Spain')]))
    P.append(dict(text='Gaspar de Guzmán, conde-duque de Olivares, fue el valido de Felipe IV, que subió al trono en 1621 con dieciséis años. Olivares fue una figura clave en la política del Estado hasta enero de 1643. Según una fuente, durante su gobierno forzó a España en la política exterior y no consiguió llevar a cabo una reforma interior. Quiso recuperar los Países Bajos, lo que renovó la guerra de los Ochenta Años mientras España estaba también implicada en la guerra de los Treinta Años (1618-1648).',
        quotes=[Q('en_olivares','When Philip IV ascended the throne in 1621, at the age of sixteen'), Q('es_olivares','valido del rey Felipe IV de España'), Q('en_olivares','was a key figure that shaped state policy in Spain until January 1643'), Q('en_olivares','His policy of committing Spain to recapture Holland led to a renewal of the Eighty Years\' War while Spain was also embroiled in the Thirty Years\' War (1618–1648).')]))
    P.append(dict(text='El proyecto de Olivares era una reforma de la monarquía compuesta, formada por reinos con distintos impuestos, privilegios y obligaciones militares. Su Unión de Armas pretendía que los diferentes territorios aportaran cuotas fijas de soldados según su tamaño y población. Una fuente la sitúa en 1624 y otra señala que en 1626 se convocaron cortes en Aragón, Cataluña y Valencia; las Cortes de Aragón aprobaron 144 000 libras jaquesas en quince años, con las que solo se podían costear 2000 hombres, frente a los 3333 listos para la guerra que Olivares había previsto. El plan fracasó por la oposición de las provincias, sobre todo Cataluña.',
        quotes=[Q('en_olivares','These plans took form first in Olivares\' \'Union of Arms\' concept, put forward in 1624.'), Q('es_olivares','El conde-duque de Olivares había previsto que Aragón aportase 3 333 hombres listos para la guerra y 10 000 reservistas.'), Q('es_olivares','aprobaron el pago de 144 000 libras jaquesas a pagar en 15 años','solamente se podían costear 2 000 hombres'), Q('en_olivares','Olivares\' \'Union of Arms\' plan failed in the face of opposition from the provinces, in particular Catalonia'), Q('en_olivares','Each part had different taxation, privileges and military arrangements')]))
    P.append(dict(text='Los intentos de centralizar el poder y de aumentar los impuestos de guerra provocaron las sublevaciones de Cataluña y Portugal, que precipitaron la caída de Olivares. Francia apoyó a los catalanes sublevados desde 1640, y España respondió apoyando a la Fronda. En las negociaciones de Westfalia, en 1648, Francia se quedó con territorios de Alsacia y controló Lorena, con lo que cerró el llamado Camino Español que unía las posesiones españolas de Italia y Flandes. España firmó la paz con las Provincias Unidas pero continuó la guerra con Francia.',
        quotes=[Q('en_olivares','his attempts to centralise power and increase wartime taxation led to revolts in Catalonia and in Portugal, which brought about his downfall'), Q('es_pirineos','En 1640 Francia comenzó a interferir en la política española, apoyando a los sublevados catalanes durante la sublevación de Cataluña'), Q('es_pirineos','cerrando el llamado Camino Español que unía las posesiones españolas en Italia y en Flandes a través de Suiza y el Franco Condado'), Q('es_pirineos','al tiempo que España apoyaba la Revuelta de la Fronda en 1648')]))
    P.append(dict(text='La guerra con Francia terminó con el Tratado de los Pirineos, firmado el 7 de noviembre de 1659 en la isla de los Faisanes por Luis de Haro y por el cardenal Mazarino. Francia recibió en el norte plazas de Artois y de Flandes, y en el sur el Rosellón, el Conflent, el Vallespir y parte de la Cerdaña, de modo que la frontera con España se fijó desde entonces siguiendo los Pirineos, salvo el enclave de Llivia y el Valle de Arán. España había perdido en 1658 la batalla de las Dunas contra Francia y su aliada Inglaterra.',
        quotes=[Q('es_pirineos','un tratado internacional suscrito el 7 de noviembre de 1659 por Luis de Haro y Mazarino'), Q('es_pirineos','se concertó la cesión a Francia del Rosellón, el Conflent, el Vallespir y una parte de la Cerdaña'), Q('en_pirineos','An Anglo-French alliance was victorious at the Battle of the Dunes on 14 June 1658')]))
    P.append(dict(text='Carlos II nació en Madrid el 6 de noviembre de 1661 y fue rey de 1665 a 1700, con cuatro años, bajo la regencia de su madre, Mariana de Austria, hasta 1675. Fue el último monarca de la Casa de Habsburgo, que gobernaba España desde 1516. Sufrió problemas de salud durante toda su vida, cuyas causas se discuten: se ha atribuido a los matrimonios consanguíneos de su familia, y se han propuesto diagnósticos como el síndrome de Klinefelter o el síndrome X frágil. Su apodo, el Hechizado, viene de la atribución posterior de su estado a la brujería.',
        quotes=[Q('es_carlos2','Madrid, 6 de noviembre de 1661-Madrid, 1 de noviembre de 1700'), Q('es_carlos2','permaneciendo bajo la regencia de su madre hasta que alcanzó la mayoría de edad en 1675'), Q('es_carlos2','es probable que los sucesivos matrimonios consanguíneos'), Q('es_carlos2','Algunos historiadores han sugerido que el heredero padecía síndrome de Klinefelter'), Q('es_carlos2','Aunque su sobrenombre le vino posteriormente de la atribución de su estado físico a la brujería e influencias diabólicas'), Q('en_carlos2','For reasons still debated, Charles experienced lengthy periods of ill health throughout his life.')]))
    P.append(dict(text='Como Carlos II no tenía hijos, la cuestión de su sucesión fue durante gran parte de su reinado un asunto central de la diplomacia europea. Los principales candidatos eran Carlos de Austria, hijo menor del emperador Leopoldo I, y Felipe de Anjou, nieto de Luis XIV. En septiembre de 1700 Carlos cayó enfermo y, según una fuente, Portocarrero lo convenció de que nombrase heredero a Felipe de Anjou. Murió el 1 de noviembre de 1700, a los 38 años, y su muerte sin descendencia dio origen a la guerra de Sucesión.',
        quotes=[Q('en_carlos2','The leading candidates for the succession were Charles of Austria, younger son of Leopold I, Holy Roman Emperor, and Philip of Anjou, 16-year-old grandson of Louis XIV of France.'), Q('en_carlos2','Luis Manuel Fernández de Portocarrero persuaded him to appoint Louis XIV\'s grandson, Philip of Anjou, as his heir. He died on 1 November 1700, at age 38.'), Q('es_carlos2','su muerte sin dejar descendencia llevó a un conflicto internacional por la cuestión de su sucesión')]))
    P.append(dict(role='definition', text='Valido: favorito del rey que ejerce de hecho el gobierno. Olivares lo fue de Felipe IV: cuando el rey subió al trono, ordenó que todos los papeles que requiriesen su firma se enviaran primero al conde-duque.',
        quotes=[Q('es_olivares','valido del rey Felipe IV de España'), Q('en_olivares','he showed his confidence in Olivares by ordering that all papers requiring the royal signature should first be sent to the count-duke')]))
    P.append(dict(role='consejo', text='Cuando una cifra histórica parezca inverosímil, compruebe primero su coherencia interna: si el número de expulsados es mayor que la población que debía ser expulsada, al menos una de las dos cifras es errónea o se refiere a otra cosa. Solo después busque una tercera fuente.',
        quotes=[Q('es_moriscos','La población morisca consistía en unas 325 000 personas'), Q('es_moriscos','En total fueron expulsadas unas 350 000 personas'), Q('en_moriscos','Dadson estimates that, out of a Morisco population of 500,000')]))
    P.append(dict(role='self_check', text='¿Por qué las cifras sobre los moriscos expulsados son problemáticas? ¿Qué pretendía la Unión de Armas y por qué fracasó? ¿Qué se pactó en el Tratado de los Pirineos? ¿Por qué la muerte de Carlos II desembocó en una guerra?',
        quotes=[Q('en_olivares','Olivares\' \'Union of Arms\' plan failed in the face of opposition from the provinces'), Q('es_pirineos','La frontera con España se fijará desde entonces siguiendo los Pirineos')]))
    return P

def problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='Una fuente afirma que fueron expulsadas unas 350 000 personas y que la población morisca era de unas 325 000. Calcule qué porcentaje de la población morisca representan los expulsados si se toman las dos cifras al pie de la letra, y comente qué conclusión puede sacarse.',
        expected='107.7', quotes=[Q('es_moriscos','En total fueron expulsadas unas 350 000 personas'), Q('en_moriscos','Dadson estimates that, out of a Morisco population of 500,000, a figure accepted by many, around 40% avoided expulsion altogether')],
        method='Comprobación de coherencia entre dos magnitudes',
        solution=dict(given=[dict(symbol='E',value=350000,unit='dimensionless',meaning='expulsados según la fuente'),dict(symbol='M',value=325000,unit='dimensionless',meaning='población morisca según la misma fuente'),dict(symbol='M_D',value=500000,unit='dimensionless',meaning='población morisca según Dadson, en la otra fuente'),dict(symbol='a',value=0.4,unit='dimensionless',meaning='fracción que evitó la expulsión según Dadson')],
          unknown='El porcentaje E/M y, como contraste, los expulsados que resultan de la estimación de Dadson.',
          model=[dict(name='Proporción de expulsados',latex='p = 100\\,\\frac{E}{M}',symbolic='100*E/M'),dict(name='Expulsados según Dadson',latex='E_D = (1-a)\\,M_D',symbolic='(1-a)*M_D')],
          assumptions=['Se toman las cifras al pie de la letra, aunque son estimaciones.','La estimación de Dadson se aplica a su propia población de 500 000, sin mezclarla con la otra fuente.'],
          development=['Si los expulsados superan a la población total, las dos cifras no pueden ser ciertas a la vez: eso no dice cuál es la errónea.'],
          steps=[dict(text='Proporción de expulsados',equation='p = 100 \\cdot 350\\,000 / 325\\,000',expression='100*350000/325000',expected=107.6923,unit='dimensionless'),
                 dict(text='Expulsados según Dadson',equation='E_D = (1 - 0{,}4) \\cdot 500\\,000',expression='(1-0.4)*500000',expected=300000,unit='dimensionless')],
          result='Con las cifras de la primera fuente, los expulsados serían el 107,7 % de la población morisca, que es imposible; con la estimación de Dadson, serían unos 300 000, cifra compatible con el rango de 275 000 a 300 000 de Lapeyre.',
          interpretation='Un porcentaje superior al 100 % indica que al menos una de las dos cifras de la primera fuente es errónea o no mide lo mismo. La estimación de 500 000 moriscos, con un 40 % que evitó la expulsión, da un número de expulsados coherente con las estimaciones tradicionales.',
          limitations=['El cálculo no demuestra cuál de las dos cifras es la errónea ni cuál es la población morisca real.'],
          mistakes=['Corregir la incoherencia ajustando una de las cifras hasta que cuadre, sin tener una tercera fuente que la respalde.']))]
